// ─── File: demo/SegmentStorageDemo.java ───
package com.bank.storage.demo;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class SegmentStorageDemo {

    private static final Logger log = Logger.getLogger(SegmentStorageDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        Partition ledger = new Partition("account.ledger-0");

        // Segment 0 (base offset 0), then rolled; segment 10 (base offset 10) active.
        ledger.appendClosedSegment(0, List.of(
                new Rec(0, "SAV2001", "DEPOSIT 100000", 1),
                new Rec(1, "CUR3001", "DEPOSIT 50000", 2),
                new Rec(2, "SAV2001", "WITHDRAW 20000", 3)));
        ledger.appendClosedSegment(3, List.of(
                new Rec(3, "SAV2001", "DEPOSIT 5000", 4),
                new Rec(4, "CUR3001", "WITHDRAW 10000", 5)));
        ledger.appendActiveSegment(5, List.of(
                new Rec(5, "SAV2001", "DEPOSIT 1000", 100))); // active, newest

        log.info("=== On-disk layout ===");
        ledger.describe(log);

        log.info("=== Offset index lookup for offset 4 ===");
        ledger.lookup(4, log);

        log.info("=== Retention: delete whole segments older than cutoff ts=3 ===");
        new RetentionPolicy(/*cutoffTs*/ 3).apply(ledger, log); // base seg (max ts 3) eligible
        ledger.describe(log);

        log.info("=== Compaction on a compacted state partition ===");
        Partition state = new Partition("account.state-0");
        state.appendClosedSegment(0, List.of(
                new Rec(0, "SAV2001", "bal=100000", 1),
                new Rec(1, "CUR3001", "bal=50000", 2),
                new Rec(2, "SAV2001", "bal=80000", 3),   // supersedes offset 0
                new Rec(3, "SAV2001", "bal=81000", 4))); // supersedes offset 2
        state.appendActiveSegment(4, List.of(new Rec(4, "CUR3001", "bal=40000", 5)));
        new Compactor().compact(state, log);
        state.describe(log);
        log.info("Note offset gaps: compaction keeps latest-per-key, preserves surviving offsets");
    }
}

// ─── Would be in LogRecord.java (Rec) in a real project ───
class Rec {
    final long offset; final String key; final String value; final long ts;
    Rec(long offset, String key, String value, long ts) { this.offset = offset; this.key = key; this.value = value; this.ts = ts; }
}

// ─── Would be in OffsetIndex.java in a real project ───
class OffsetIndex {
    // sparse: offset -> byte position (one entry every few records in reality)
    final Map<Long, Integer> entries = new LinkedHashMap<>();
    void addSparse(long offset, int bytePos) { entries.put(offset, bytePos); }
    long floorOffset(long target) {
        long best = -1;
        for (Long o : entries.keySet()) if (o <= target && o > best) best = o;
        return best;
    }
}

// ─── Would be in Segment.java in a real project ───
class Segment {
    final long baseOffset;
    final List<Rec> recs = new ArrayList<>();
    final OffsetIndex index = new OffsetIndex();
    boolean active;

    Segment(long baseOffset, boolean active) { this.baseOffset = baseOffset; this.active = active; }

    void load(List<Rec> records) {
        int bytePos = 0;
        for (int i = 0; i < records.size(); i++) {
            recs.add(records.get(i));
            if (i % 2 == 0) index.addSparse(records.get(i).offset, bytePos); // sparse every 2
            bytePos += 128;
        }
    }
    long maxTimestamp() { return recs.stream().mapToLong(r -> r.ts).max().orElse(0); }
    String name() { return String.format("%020d", baseOffset); }
}

// ─── Would be in Partition.java in a real project ───
class Partition {
    final String dir;
    final List<Segment> segments = new ArrayList<>();
    Partition(String dir) { this.dir = dir; }

    void appendClosedSegment(long base, List<Rec> recs) { Segment s = new Segment(base, false); s.load(recs); segments.add(s); }
    void appendActiveSegment(long base, List<Rec> recs) { Segment s = new Segment(base, true); s.load(recs); segments.add(s); }

    void describe(Logger log) {
        for (Segment s : segments) {
            log.info(dir + "/" + s.name() + ".log (.index/.timeindex) records=" + s.recs.size()
                    + (s.active ? " [ACTIVE — never cleaned]" : " [closed]"));
        }
    }

    void lookup(long offset, Logger log) {
        for (Segment s : segments) {
            if (offset >= s.baseOffset && offset < s.baseOffset + s.recs.size()) {
                long nearest = s.index.floorOffset(offset);
                log.info("offset " + offset + " in segment " + s.name()
                        + ": index floor=" + nearest + " -> seek + scan forward to " + offset);
                return;
            }
        }
        log.warning("offset " + offset + " not found (may have been retained/compacted away)");
    }
}

// ─── Would be in RetentionPolicy.java in a real project ───
class RetentionPolicy {
    private final long cutoffTs;
    RetentionPolicy(long cutoffTs) { this.cutoffTs = cutoffTs; }
    void apply(Partition p, Logger log) {
        p.segments.removeIf(s -> {
            boolean eligible = !s.active && s.maxTimestamp() <= cutoffTs;
            if (eligible) log.info("Deleting WHOLE segment " + s.name() + " (maxTs " + s.maxTimestamp() + ")");
            return eligible;
        });
    }
}

// ─── Would be in Compactor.java in a real project ───
class Compactor {
    void compact(Partition p, Logger log) {
        Map<String, Rec> latest = new LinkedHashMap<>();
        for (Segment s : p.segments) if (!s.active)
            for (Rec r : s.recs) latest.put(r.key, r); // latest per key across closed segs
        for (Segment s : p.segments) {
            if (s.active) continue;
            s.recs.removeIf(r -> latest.get(r.key) != r); // drop superseded, keep latest
        }
        log.info("Compacted closed segments to latest-per-key (active segment untouched)");
    }
}

// ─── Would be in BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    public String format(LogRecord r) {
        return String.format("[%1$tF %1$tT] [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
